export const authApi = {
  requestLink: (email: string) =>
    api<RequestLinkResponse>("/auth/request-link", {
      method: "POST",
      body: JSON.stringify({ email }),
    }),

  verify: (token: string) =>
    api<VerifyResponse>(`/auth/verify?token=${encodeURIComponent(token)}`),

  logout: () =>
    api<{ message: string }>("/auth/logout", {
      method: "POST",
    }),
};

// Channels API
export const channelsApi = {
  list: (params?: { category?: string; type?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.category) searchParams.set("category", params.category);
    if (params?.type) searchParams.set("type", params.type);
    const query = searchParams.toString();
    return api<ChannelListResponse>(`/channels${query ? `?${query}` : ""}`);
  },

  request: (type: string, url: string) =>
    api<ChannelRequestResponse>("/channels/request", {
      method: "POST",
      body: JSON.stringify({ type, url }),
    }),

  myRequests: () => api<MyChannelRequest[]>("/channels/requests/mine"),
};

// Subscriptions API
export const subscriptionsApi = {
  list: () => api<SubscriptionListResponse>("/subscriptions"),

  create: (channelId: string) =>
    api<CreateSubscriptionResponse>("/subscriptions", {
      method: "POST",
      body: JSON.stringify({ channel_id: channelId }),
    }),

  delete: (subscriptionId: string) =>
    api<{ message: string }>(`/subscriptions/${subscriptionId}`, {
      method: "DELETE",
    }),

  backfill: (subscriptionId: string, limit: number = 5) =>
    api<{ episodes_queued: number; message: string }>(
      `/subscriptions/${subscriptionId}/backfill`,
      {
        method: "POST",
        body: JSON.stringify({ limit }),
      }
    ),

  getEpisodes: (subscriptionId: string, page: number = 1, perPage: number = 20) =>
    api<EpisodeListResponse>(
      `/subscriptions/${subscriptionId}/episodes?page=${page}&per_page=${perPage}`
    ),

  requestEpisode: (subscriptionId: string, episodeId: string) =>
    api<RequestEpisodeResponse>(
      `/subscriptions/${subscriptionId}/episodes/request`,
      {
        method: "POST",
        body: JSON.stringify({ episode_id: episodeId }),
      }
    ),
};

// Episodes API
export const episodesApi = {
  getSummary: (episodeId: string) =>
    api<SummaryResponse>(`/episodes/${episodeId}/summary`),

  resend: (episodeId: string) =>
    api<ResendResponse>(`/episodes/${episodeId}/resend`, {
      method: "POST",
    }),
};

// Users API
export const usersApi = {
  getUsage: () => api<UsageResponse>("/users/me/usage"),

  getPreferences: () =>
    api<{ preferences: SummaryPreferences }>("/users/me/preferences"),

  updatePreferences: (preferences: SummaryPreferences) =>
    api<UpdatePreferencesResponse>("/users/me/preferences", {
      method: "PUT",
      body: JSON.stringify({ preferences }),
    }),
};

// Admin API
export const adminApi = {
  // Dashboard
  getDashboardStats: () => api<AdminDashboardStats>("/admin/dashboard/stats"),
  getDashboardErrors: () => api<AdminDashboardErrors>("/admin/dashboard/errors"),

  // Users
  getUsers: (params: { page?: number; search?: string }) => {
    const searchParams = new URLSearchParams();
    if (params.page) searchParams.set("page", String(params.page));
    if (params.search) searchParams.set("search", params.search);
    const query = searchParams.toString();
    return api<AdminPaginatedResponse<AdminUserSummary>>(
      `/admin/users${query ? `?${query}` : ""}`
    );
  },
  deleteUser: (userId: string) =>
    api<void>(`/admin/users/${userId}`, { method: "DELETE" }),

  // Channels
  getChannels: (params: { page?: number; search?: string; type?: string }) => {
    const searchParams = new URLSearchParams();
    if (params.page) searchParams.set("page", String(params.page));
    if (params.search) searchParams.set("search", params.search);
    if (params.type) searchParams.set("type", params.type);
    const query = searchParams.toString();
    return api<AdminPaginatedResponse<AdminChannelSummary>>(
      `/admin/channels${query ? `?${query}` : ""}`
    );
  },
  createChannel: (data: { type: string; name: string; category?: string }) =>
    api<AdminChannelSummary>("/admin/channels", {
      method: "POST",
      body: JSON.stringify(data),
    }),
  updateChannel: (
    channelId: string,
    data: {
      name?: string;
      category?: string;
      description?: string;
      image_url?: string;
      listen_url?: string;
      is_active?: boolean;
    }
  ) =>
    api<AdminChannelSummary>(`/admin/channels/${channelId}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),
  deleteChannel: (channelId: string) =>
    api<void>(`/admin/channels/${channelId}`, { method: "DELETE" }),

  // Channel Requests
  getChannelRequests: (params: { page?: number; status?: string }) => {
    const searchParams = new URLSearchParams();
    if (params.page) searchParams.set("page", String(params.page));
    if (params.status) searchParams.set("status", params.status);
    const query = searchParams.toString();
    return api<AdminPaginatedResponse<AdminChannelRequestSummary>>(
      `/admin/channel-requests${query ? `?${query}` : ""}`
    );
  },
  approveRequest: (requestId: string, data: { name: string; category?: string }) =>
    api<AdminChannelSummary>(`/admin/channel-requests/${requestId}/approve`, {
      method: "POST",
      body: JSON.stringify(data),
    }),
  rejectRequest: (requestId: string, data?: { admin_notes?: string }) =>
    api<void>(`/admin/channel-requests/${requestId}/reject`, {
      method: "POST",
      body: JSON.stringify(data || {}),
    }),

  // Deliveries
  getDeliveries: (params: { page?: number; status?: string }) => {
    const searchParams = new URLSearchParams();
    if (params.page) searchParams.set("page", String(params.page));
    if (params.status) searchParams.set("status", params.status);
    const query = searchParams.toString();
    return api<AdminPaginatedResponse<AdminDeliverySummary>>(
      `/admin/deliveries${query ? `?${query}` : ""}`
    );
  },
  retryDelivery: (deliveryId: string) =>
    api<void>(`/admin/deliveries/${deliveryId}/retry`, { method: "POST" }),
  cancelDelivery: (deliveryId: string) =>
    api<void>(`/admin/deliveries/${deliveryId}/cancel`, { method: "POST" }),
  bulkRetryDeliveries: (deliveryIds: string[]) =>
    api<void>("/admin/deliveries/bulk-retry", {
      method: "POST",
      body: JSON.stringify({ delivery_ids: deliveryIds }),
    }),

  // Episodes
  getEpisodes: (params: {
    page?: number;
    search?: string;
    channel_id?: string;
  }) => {
    const searchParams = new URLSearchParams();
    if (params.page) searchParams.set("page", String(params.page));
    if (params.search) searchParams.set("search", params.search);
    if (params.channel_id) searchParams.set("channel_id", params.channel_id);
    const query = searchParams.toString();
    return api<AdminPaginatedResponse<AdminEpisodeSummary>>(
      `/admin/episodes${query ? `?${query}` : ""}`
    );
  },
  reprocessEpisode: (
    episodeId: string,
    data: { reprocess_transcript?: boolean; reprocess_summary?: boolean }
  ) =>
    api<void>(`/admin/episodes/${episodeId}/reprocess`, {
      method: "POST",
      body: JSON.stringify(data),
    }),
  deleteEpisode: (episodeId: string) =>
    api<void>(`/admin/episodes/${episodeId}`, { method: "DELETE" }),

  // Stats
  getProcessingStats: (days: number = 7) =>
    api<AdminProcessingStats>(`/admin/stats/processing?days=${days}`),

  // Jobs
  triggerPoller: () => api<void>("/admin/jobs/poller/run", { method: "POST" }),
  triggerController: () =>
    api<void>("/admin/jobs/controller/run", { method: "POST" }),
  triggerProcessor: () =>
    api<void>("/admin/jobs/processor/run", { method: "POST" }),
  resetGpuCounter: () => api<void>("/admin/jobs/gpu-reset", { method: "POST" }),
};

